function FixtureMarkdown({text}){
 window.markdownInputs.push(text);window.markdownRenders++;
 const [ready,setReady]=React.useState(!window.deferMarkdown);
 React.useEffect(()=>{window.markdownMounts++;if(!ready)window.releaseMarkdown=()=>setReady(true);},[]);
 if(!ready)return h('div',{'data-markdown-loading':''},'');
 const inline=value=>{
  const values=[],pattern=/(\*\*[^*]+\*\*|`[^`]+`|\[[^\]]+\]\([^)]+\))/g,decode=text=>text.replace(/&(?:amp|#38|#x26);/gi,'&');let at=0;
  for(const match of value.matchAll(pattern)){values.push(decode(value.slice(at,match.index)));const token=match[0];
   if(token.startsWith('**'))values.push(h('strong',{key:match.index},decode(token.slice(2,-2))));
   else if(token.startsWith('`'))values.push(h('code',{key:match.index},token.slice(1,-1)));
   else values.push(h('a',{key:match.index,href:token.slice(token.indexOf('](')+2,-1)},decode(token.slice(1,token.indexOf('](')))));
   at=match.index+token.length;
  }values.push(decode(value.slice(at)));return values;
 };
 return h('div',{'data-host-markdown':''},...text.split('\n\n').map((block,index)=>{
  if(block.startsWith('```'))return h('div',{key:index,className:'host-code'},h('button',{type:'button'},'复制代码'),h('pre',null,h('code',null,h('span',{'data-syntax-token':'command',style:{color:'#8767c7'}},'node'),block.split('\n')[1].slice(4))));
  if(/^#{1,6} /.test(block)){const marker=/^(#{1,6}) /.exec(block);return h('h'+marker[1].length,{key:index},block.slice(marker[0].length));}
  if(block.startsWith('- '))return h('ul',{key:index},...block.split('\n').map((line,n)=>h('li',{key:n},...inline(line.slice(2)))));
  if(block.startsWith('|')){const rows=block.split('\n').map(line=>line.split('|').slice(1,-1).map(s=>s.trim()));return h('table',{key:index},h('thead',null,h('tr',null,...rows[0].map((v,n)=>h('th',{key:n},v)))),h('tbody',null,...rows.slice(2).map((row,n)=>h('tr',{key:n},...row.map((v,c)=>h('td',{key:c},v))))));}
  if(block.startsWith('> '))return h('blockquote',{key:index},h('p',null,...inline(block.slice(2))));
  return h('p',{key:index},...inline(block));
 }));
}
